/* ===================================================================
   Matebase · glosario.js
   EL VOCABULARIO. Cada entrada: {t: termino, d: definicion, v: variantes
   para la busqueda (opcional), i: tema donde se explica (opcional)}.

   Criterios al escribir una definicion:
     - Frase entera, no telegrama. El alumno llega aqui perdido.
     - Primero que ES, despues para que sirve o donde aparece.
     - Si una palabra significa cosas distintas en sitios distintos,
       una entrada por acepcion, diciendolo.
   =================================================================== */
window.GLOSARIO = [

/* ---------------- lógica y conjuntos ---------------- */
{ t: 'Proposición', d: 'Una frase de la que se puede decir, sin discusión, si es verdadera o falsa. «Siete es primo» lo es; «qué hora es» no, y «esta película es buena» tampoco, porque no hay manera de decidirlo. Toda la lógica se construye encima de esta idea.', i: 'lg-proposiciones' },
{ t: 'Conectiva', d: 'Cada una de las palabras con las que se enganchan proposiciones para formar otras más largas: <strong>y</strong>, <strong>o</strong>, <strong>no</strong>, <strong>si… entonces</strong>. Se llaman así porque conectan. Lo importante es que el valor de verdad del resultado queda determinado por el de las piezas, y eso es lo que permite calcular con frases.', v: 'conectiva lógica conector', i: 'lg-proposiciones' },
{ t: 'Tabla de verdad', d: 'La tabla que recoge todos los casos posibles de verdadero y falso para las proposiciones simples, y qué sale en cada uno. Con dos proposiciones hay cuatro filas; con tres, ocho. Es, literalmente, el plano de un circuito digital.', i: 'lg-proposiciones' },
{ t: 'Implicación', d: 'La conectiva «si A, entonces B». Solo es falsa en un caso: cuando A es verdadera y B falsa. Cuidado, porque no significa que A cause B, y no se puede dar la vuelta: que llover implique mojarse no significa que mojarse implique llover.', v: 'implicacion condicional si entonces', i: 'lg-proposiciones' },
{ t: 'Recíproca', d: 'Dada la implicación «si A entonces B», su recíproca es «si B entonces A». <strong>No son equivalentes</strong>, y confundirlas es el error clásico: que una prueba médica dé positivo en los enfermos no significa que todo positivo esté enfermo.', v: 'reciproca reciproco', i: 'lg-proposiciones' },
{ t: 'Contrarrecíproca', d: 'Dada «si A entonces B», su contrarrecíproca es «si no B, entonces no A». Esta sí es siempre equivalente a la original, y por eso demostrarla vale como demostración. A menudo es mucho más fácil de probar que la de partida.', v: 'contrarreciproca contrapositiva', i: 'lg-proposiciones' },
{ t: 'Cuantificador', d: 'La palabra que dice a cuántos elementos se aplica una propiedad. Hay dos: el universal <strong>∀</strong>, «para todo», y el existencial <strong>∃</strong>, «existe algún». Para tumbar un «para todo» basta un contraejemplo; para tumbar un «existe» hay que descartarlos todos.', i: 'lg-proposiciones' },
{ t: 'Contraejemplo', d: 'Un caso concreto que incumple una afirmación general y, por tanto, la destruye. Un solo contraejemplo basta: si alguien dice que todos los primos son impares, el 2 zanja la discusión.', i: 'lg-demostracion' },
{ t: 'Inducción', d: 'Método para demostrar que algo se cumple para todos los números naturales, sin comprobarlos uno a uno. Se demuestra el primer caso y se demuestra que, si vale para uno cualquiera, vale para el siguiente. Es el efecto dominó: tira la primera ficha y garantiza que cada una tira a la siguiente.', v: 'induccion principio de induccion', i: 'lg-demostracion' },
{ t: 'Reducción al absurdo', d: 'Demostrar algo suponiendo lo contrario y llegando a una contradicción. Si suponer que no se cumple lleva a un imposible, es que se cumple. Es como se depura una avería: «supongamos que el fallo está aquí»; si de ahí se sigue algo que no cuadra, no está ahí.', v: 'reduccion al absurdo absurdo contradiccion', i: 'lg-demostracion' },
{ t: 'Conjunto', d: 'Una colección de objetos bien determinada: dado cualquier objeto, tiene que estar claro si pertenece o no. No se pide nada más, ni orden, ni cantidad, ni que se parezcan entre sí. Con esta idea tan pobre se construye toda la matemática.', i: 'lg-conjuntos' },
{ t: 'Por extensión y por comprensión', d: 'Las dos maneras de dar un conjunto. <strong>Por extensión</strong> es enumerar sus elementos, {1, 2, 3, 4}. <strong>Por comprensión</strong> es dar la regla que cumplen, sin listarlos: «los naturales menores que 5 distintos de cero». La segunda es la única viable cuando hay infinitos.', v: 'extension comprension' , i: 'lg-conjuntos' },
{ t: 'Pertenencia (∈)', d: 'La relación entre un <em>elemento</em> y un conjunto: se lee «pertenece a». No confundir con la inclusión ⊂, que relaciona dos <em>conjuntos</em>. Si A = {1,2}, entonces 1 ∈ A y {1} ⊂ A, pero «1 ⊂ A» no significa nada.', v: 'pertenencia pertenece elemento', i: 'lg-conjuntos' },
{ t: 'Subconjunto (⊂)', d: 'A es subconjunto de B cuando todos los elementos de A están también en B. El conjunto vacío es subconjunto de todos, y todo conjunto es subconjunto de sí mismo.', v: 'subconjunto inclusion contenido', i: 'lg-conjuntos' },
{ t: 'Unión e intersección', d: 'Las dos operaciones básicas entre conjuntos. La <strong>unión</strong> (∪) reúne lo que está en uno <em>o</em> en otro; la <strong>intersección</strong> (∩) se queda solo con lo que está en los dos <em>a la vez</em>. Son el «o» y la «y» de la lógica, dibujados.', v: 'union interseccion', i: 'lg-conjuntos' },
{ t: 'Conjunto vacío (∅)', d: 'El conjunto que no tiene ningún elemento. Parece inútil y no lo es: aparece cada vez que dos cosas no tienen nada en común, y es subconjunto de cualquier conjunto.', v: 'vacio conjunto vacio', i: 'lg-conjuntos' },
{ t: 'Cardinal', d: 'El número de elementos de un conjunto; se escribe entre barras, |A|. Para conjuntos infinitos la idea se refina y da lugar a resultados sorprendentes, como que haya más números reales que naturales.', i: 'lg-conjuntos' },
{ t: 'Producto cartesiano', d: 'Dados dos conjuntos, el conjunto de todas las <em>parejas ordenadas</em> que se pueden formar tomando uno de cada. Aquí el orden importa: (1,2) no es (2,1). El plano entero es el producto cartesiano de los reales consigo mismos.', v: 'producto cartesiano pares ordenados', i: 'lg-conjuntos' },
{ t: 'Aplicación', d: 'Otro nombre de <em>función</em>: una regla que asigna a cada elemento de un conjunto <strong>exactamente uno</strong> de otro. Las dos exigencias hacen todo el trabajo: «a cada» prohíbe dejar a alguien sin asignar, y «exactamente uno» prohíbe la ambigüedad.', v: 'aplicacion funcion', i: 'lg-conjuntos' },
{ t: 'Inyectiva, sobreyectiva, biyectiva', d: 'Las tres formas de repartir de una aplicación. <strong>Inyectiva</strong>: nadie comparte destino (por eso un DNI identifica). <strong>Sobreyectiva</strong>: no sobra nadie en el conjunto de llegada. <strong>Biyectiva</strong>: las dos cosas, un emparejamiento perfecto, y por eso se puede deshacer.', v: 'inyectiva sobreyectiva biyectiva inyectividad', i: 'lg-conjuntos' },

/* ---------------- aritmética ---------------- */
{ t: 'Valor posicional', d: 'La idea de que una cifra vale distinto según el lugar que ocupa: el 3 de 300 vale trescientos y el de 3 vale tres. Es lo que hace que con diez símbolos se escriba cualquier número, y lo que permite que un ordenador cuente con solo dos.', i: 'ar-naturales' },
{ t: 'Divisor y múltiplo', d: 'Son la misma relación vista desde los dos lados: si 3 divide a 12, entonces 12 es múltiplo de 3. «Divide» significa que la división es exacta, sin resto.', v: 'divisor multiplo divisibilidad', i: 'ar-divisibilidad' },
{ t: 'Número primo', d: 'Un número mayor que 1 que solo se puede dividir exactamente por 1 y por sí mismo. Son los ladrillos con los que se construyen todos los demás por multiplicación, y su dificultad para ser recuperados de un producto sostiene el cifrado de internet. El 1 no se considera primo, por convenio útil.', v: 'primo primos', i: 'ar-divisibilidad' },
{ t: 'Factorizar', d: 'Escribir algo como un producto. Un número, como producto de primos: 60 = 2²·3·5. Un polinomio, como producto de polinomios más simples. Es la operación que permite simplificar fracciones y resolver ecuaciones, porque un producto vale cero solo si algún factor vale cero.', v: 'factorizar factorizacion descomposicion', i: 'al-identidades' },
{ t: 'm.c.d. y m.c.m.', d: 'El <strong>máximo común divisor</strong> es el número más grande que divide a varios a la vez; sirve para simplificar y para repartir sin cortar. El <strong>mínimo común múltiplo</strong> es el más pequeño que es múltiplo de todos; responde a «¿cuándo volverá a coincidir?».', v: 'mcd mcm maximo comun divisor minimo comun multiplo', i: 'ar-divisibilidad' },
{ t: 'Valor absoluto', d: 'La distancia de un número al cero, sin importar el signo: |−5| = 5. Responde a «¿cuánto me he desviado?» cuando da igual hacia qué lado, que es lo que necesita un termostato o una medida de error.', i: 'ar-enteros' },
{ t: 'Fracción irreducible', d: 'La fracción que ya no se puede simplificar más, porque numerador y denominador no comparten ningún factor. Toda fracción tiene una sola forma irreducible, y por eso es la manera canónica de dar un resultado.', v: 'irreducible simplificar fraccion', i: 'ar-fracciones' },
{ t: 'Número racional', d: 'El que se puede escribir como fracción de dos enteros. Su marca de identidad es que su expresión decimal o se corta o se repite periódicamente. Se les llama racionales por «razón», es decir, cociente, no por ser sensatos.', v: 'racional racionales fraccion', i: 'ar-conjuntos' },
{ t: 'Número irracional', d: 'El que <strong>no</strong> se puede escribir como fracción; sus decimales no acaban ni se repiten nunca. √2, π y e lo son. El folio A4 tiene los lados en razón √2, que es la única proporción que se conserva al doblar la hoja por la mitad.', v: 'irracional irracionales', i: 'ar-conjuntos' },
{ t: 'Intervalo', d: 'Un tramo de la recta real. Se escribe con corchete si el extremo entra, [2,5], y con paréntesis si no, (2,5). Fuera del aula casi nada se especifica con un número exacto sino con un intervalo: una tolerancia, un rango de referencia, un margen.', i: 'ar-conjuntos' },
{ t: 'Potencia', d: 'Una multiplicación abreviada: la <em>base</em> es lo que se repite y el <em>exponente</em>, cuántas veces. Ojo, 2⁵ no es 2·5 sino 32. Que el exponente pueda ser cero, negativo o fraccionario no es un capricho: es lo único que mantiene las propiedades sin excepciones.', v: 'potencia exponente base', i: 'ar-potencias' },
{ t: 'Raíz', d: 'La operación que deshace una potencia: la raíz enésima de a es el número que elevado a n da a. Se puede escribir como potencia de exponente fraccionario, y con eso raíces y potencias dejan de ser dos mundos.', v: 'raiz radical radicando indice', i: 'ar-potencias' },
{ t: 'Notación científica', d: 'Escribir un número como un valor entre 1 y 10 multiplicado por una potencia de diez: 0,00034 es 3,4·10⁻⁴. No sirve solo para ahorrar ceros; sirve para comparar de un vistazo, mirando solo el exponente.', v: 'notacion cientifica', i: 'ar-potencias' },
{ t: 'Cifras significativas', d: 'Las cifras de una medida que de verdad se han medido. Escribir más de las que tienes es afirmar algo que no sabes: dar una coordenada de GPS al milímetro es inventarse los últimos dígitos.', v: 'cifras significativas precision', i: 'ar-magnitudes' },
{ t: 'Análisis dimensional', d: 'Comprobar que las unidades de una fórmula cuadran antes de calcular nada. Si al despejar te queda una velocidad igualada a una aceleración, ya sabes que está mal sin revisar las cuentas. Es un detector de errores que cuesta diez segundos.', v: 'analisis dimensional unidades dimensiones', i: 'ar-magnitudes' },
{ t: 'Proporcionalidad directa e inversa', d: '<strong>Directa</strong>: al multiplicar una magnitud por un número, la otra queda multiplicada por el mismo; lo constante es el cociente. <strong>Inversa</strong>: la otra queda dividida; lo constante es el producto. Más kilos, más precio es directa; más obreros, menos tiempo es inversa.', v: 'proporcionalidad directa inversa proporcional', i: 'ar-proporcionalidad' },
{ t: 'Interés compuesto', d: 'El que se calcula no solo sobre el capital inicial sino también sobre los intereses ya generados. Es la razón de que una hipoteca larga cueste tanto más que el dinero prestado, y de que empezar a ahorrar diez años antes importe más que ahorrar el doble.', v: 'interes compuesto simple', i: 'ar-proporcionalidad' },

/* ---------------- álgebra ---------------- */
{ t: 'Incógnita', d: 'La letra que representa el número desconocido que hay que averiguar. Se distingue de un <em>parámetro</em>, que también es una letra pero representa un dato fijo aunque no se diga cuál.', v: 'incognita variable parametro', i: 'al-lenguaje' },
{ t: 'Monomio y polinomio', d: 'Un <strong>monomio</strong> es un producto de un número por potencias de letras, como 5x³. Un <strong>polinomio</strong> es una suma de monomios. Solo se pueden sumar monomios <em>semejantes</em>, los que tienen la misma parte literal, porque no se suman peras con manzanas.', v: 'monomio polinomio termino grado semejantes', i: 'al-lenguaje' },
{ t: 'Grado', d: 'De un monomio, la suma de los exponentes de sus letras. De un polinomio, el mayor grado de sus monomios. Es lo que decide el aspecto de la gráfica y cuántas soluciones puede tener una ecuación.', i: 'al-polinomios' },
{ t: 'Identidad', d: 'Una igualdad que se cumple para <strong>cualquier</strong> valor de las letras, a diferencia de una ecuación, que solo se cumple para algunos. (a+b)² = a²+2ab+b² es una identidad; x+2 = 5 es una ecuación.', v: 'identidad identidades notables igualdad', i: 'al-identidades' },
{ t: 'Discriminante', d: 'El número b²−4ac de una ecuación de segundo grado. Sin resolver nada, su signo dice cuántas soluciones hay: positivo dos, cero una doble, negativo ninguna real. Responde a «¿llega o no llega?» de forma muchísimo más barata que resolver.', i: 'al-ec2' },
{ t: 'Valores prohibidos', d: 'Los valores de la incógnita que hacen que una expresión no tenga sentido, típicamente los que anulan un denominador o dejan negativo lo de dentro de una raíz par. Localizarlos antes de operar evita respuestas falsas.', v: 'valores prohibidos dominio denominador', i: 'al-fracciones-alg' },
{ t: 'Logaritmo', d: 'La operación que responde a «¿a qué exponente hay que elevar la base para obtener este número?». Su gran virtud es que <strong>baja el exponente</strong>, y por eso es la herramienta para despejar una incógnita que está arriba. Solo existe para números positivos.', v: 'logaritmo log neperiano ln base', i: 'al-radicales-log' },
{ t: 'Sistema de ecuaciones', d: 'Varias ecuaciones que se tienen que cumplir <em>a la vez</em>. Con dos incógnitas, cada ecuación es una recta y resolver es buscar dónde se cortan; de ahí que pueda haber una solución, ninguna o infinitas.', v: 'sistema ecuaciones compatible incompatible determinado indeterminado', i: 'al-sistemas' },
{ t: 'Matriz', d: 'Una tabla rectangular de números. Pero pensarla como una tabla se queda corto: una matriz es una <strong>transformación</strong> —un giro, un estiramiento, una proyección—, y multiplicar dos matrices significa aplicar una después de la otra. De ahí sale la regla de fila por columna y de ahí que el producto no sea conmutativo.', i: 'al-matrices' },
{ t: 'Determinante', d: 'Un número que se asocia a toda matriz cuadrada y que concentra mucha información sobre ella. Su valor absoluto es el área (o el volumen) que genera la transformación; si vale cero, la transformación aplasta el espacio y ya no se puede deshacer.', i: 'al-matrices' },
{ t: 'Matriz inversa', d: 'La que deshace lo que hizo otra. Existe solo si el determinante no es cero, y esa condición tiene un significado claro: si la transformación perdió información por el camino, no hay manera de volver atrás.', v: 'inversa matriz inversa', i: 'al-matrices' },
{ t: 'Rango', d: 'El número de filas realmente independientes de una matriz, es decir, las que quedan sin anularse al escalonarla. Comparar el rango de la matriz de coeficientes con el de la ampliada es lo que decide si un sistema tiene solución.', i: 'al-gauss' },
{ t: 'Número complejo', d: 'Un número de la forma a+bi, donde i es la unidad imaginaria, definida por i² = −1. No nacieron para resolver x²+1=0 —eso se declaraba imposible— sino porque hacían falta como paso intermedio para resolver ecuaciones de tercer grado con soluciones reales.', v: 'complejo complejos imaginario binomica', i: 'al-complejos' },
{ t: 'Unidad imaginaria (i)', d: 'El número definido por i² = −1. Geométricamente, multiplicar por i es <strong>girar un cuarto de vuelta</strong>, y por eso i² = −1: dos cuartos de vuelta son media vuelta, que es lo que hace el signo menos.', v: 'unidad imaginaria i', i: 'al-complejos' },

/* ---------------- módulo: tres acepciones ---------------- */
{ t: 'Módulo (de un vector)', d: 'Su longitud, es decir, la distancia entre el origen y la punta de la flecha. Se escribe entre barras, |v⃗|, y se calcula con Pitágoras a partir de las componentes. Es una de las tres cosas que definen un vector, junto con dirección y sentido.', v: 'modulo vector longitud norma', i: 'ge-vectores' },
{ t: 'Módulo (de un complejo)', d: 'Su distancia al origen en el plano complejo: para a+bi vale √(a²+b²). Es la misma idea que el módulo de un vector, porque un complejo se dibuja como un punto del plano. Al multiplicar dos complejos, sus módulos se multiplican.', v: 'modulo complejo', i: 'al-complejos' },
{ t: 'Módulo n (aritmética modular)', d: 'Aquí «módulo» significa otra cosa: es el número entre el que se divide para quedarse solo con el resto. «15 ≡ 3 módulo 12» dice que 15 y 3 dejan el mismo resto al dividir entre 12, que es lo que ocurre en un reloj. Nada que ver con la longitud de un vector, pese al nombre.', v: 'modulo n modular congruencia resto reloj', i: 'av-numeros' },

/* ---------------- geometría y trigonometría ---------------- */
{ t: 'Semejanza', d: 'Dos figuras son semejantes cuando tienen la misma forma y distinto tamaño: ángulos iguales y lados proporcionales. La razón entre lados se llama razón de semejanza, y hay que recordar que las áreas van con su cuadrado y los volúmenes con su cubo.', v: 'semejanza semejante razon', i: 'ge-semejanza' },
{ t: 'Lugar geométrico', d: 'El conjunto de todos los puntos que cumplen una condición. La circunferencia es el lugar de los puntos que están a la misma distancia de un centro; la elipse, el de los que suman una distancia constante a dos focos. Definir así una figura permite traducirla a ecuación.', v: 'lugar geometrico', i: 'ge-conicas' },
{ t: 'Vector', d: 'Una flecha: sirve para las magnitudes que no quedan definidas con un solo número porque además tienen dirección, como la velocidad o una fuerza. Tiene módulo (longitud), dirección (la recta sobre la que va) y sentido (hacia dónde apunta de los dos posibles).', v: 'vector vectores', i: 'ge-vectores' },
{ t: 'Escalar', d: 'Un número corriente, cuando se lo quiere distinguir de un vector. La masa y la temperatura son escalares; la velocidad y la fuerza son vectores. Multiplicar un vector por un escalar lo estira o lo encoge.', i: 'ge-vectores' },
{ t: 'Producto escalar', d: 'Operación entre dos vectores que devuelve <strong>un número</strong>, no un vector. Mide cuánto van los dos en la misma dirección: positivo si apuntan hacia el mismo lado, cero si son perpendiculares, negativo si se oponen. Comprobar si vale cero es la forma más rápida de detectar un ángulo recto.', v: 'producto escalar', i: 'ge-vectores' },
{ t: 'Producto vectorial', d: 'Operación entre dos vectores del espacio que devuelve <strong>otro vector</strong>, perpendicular a los dos. Responde a «¿hacia dónde mira esta superficie?», que es lo que necesita cualquier motor gráfico para iluminar una escena, y describe el momento de una fuerza.', v: 'producto vectorial', i: 'ge-espacio' },
{ t: 'Rectas que se cruzan', d: 'En el espacio, dos rectas pueden no cortarse y tampoco ser paralelas: se cruzan, como dos calles a distinta altura. Es la posición que no tiene equivalente en el plano y la que más se olvida al pasar de dos a tres dimensiones.', v: 'se cruzan cruzan alabeadas posiciones relativas', i: 'ge-espacio' },
{ t: 'Radián', d: 'La unidad natural de ángulo: el ángulo cuyo arco mide lo mismo que el radio. Una vuelta completa son 2π radianes. No es un convenio como el grado: en radianes la longitud de arco es simplemente radio por ángulo, y la derivada del seno es el coseno. En grados aparecen factores feísimos.', v: 'radian radianes grados', i: 'tr-circunferencia' },
{ t: 'Razones trigonométricas', d: 'Seno, coseno y tangente: los cocientes entre los lados de un triángulo rectángulo. Su gracia es que solo dependen del ángulo, no del tamaño del triángulo, y por eso permiten medir alturas y distancias inalcanzables.', v: 'razones trigonometricas seno coseno tangente', i: 'tr-razones' },
{ t: 'Amplitud, frecuencia y fase', d: 'Los mandos de una onda. La <strong>amplitud</strong> es lo alto que sube (el volumen de un sonido); la <strong>frecuencia</strong>, cuántas veces se repite por segundo (lo grave o agudo); la <strong>fase</strong>, en qué punto del ciclo empieza. Con esos tres números y un desplazamiento se describe casi todo lo que oscila.', v: 'amplitud frecuencia fase periodo onda', i: 'tr-funciones' },

/* ---------------- funciones y análisis ---------------- */
{ t: 'Función', d: 'Una regla que asigna a cada valor de entrada exactamente un valor de salida. La definición moderna no exige que haya fórmula: basta con que la asignación esté bien determinada. Esa generalidad, que hoy parece obvia, fue revolucionaria en 1837.', v: 'funcion funciones', i: 'fn-concepto' },
{ t: 'Dominio y recorrido', d: 'El <strong>dominio</strong> son los valores de entrada que la función admite; el <strong>recorrido</strong>, los valores de salida que llega a alcanzar. En Bachillerato el dominio se calcula buscando lo prohibido: denominadores que se anulan, raíces pares de negativos y logaritmos de cero o menos.', v: 'dominio recorrido imagen rango', i: 'fn-concepto' },
{ t: 'Pendiente', d: 'Cuánto sube una recta por cada unidad que avanza. Es el número que aparece por todas partes disfrazado: el 12 % de una señal de tráfico, los euros por kilómetro de un taxi, el consumo por hora de un aparato.', i: 'fn-lineales' },
{ t: 'Asíntota', d: 'Una recta a la que la curva se acerca indefinidamente sin llegar a tocarla. No es un adorno del dibujo: suele ser un límite físico real, el techo al que tiende un rendimiento, una concentración o una velocidad.', v: 'asintota asintotas', i: 'fn-racionales' },
{ t: 'Progresión aritmética y geométrica', d: 'En la <strong>aritmética</strong>, cada término se obtiene <em>sumando</em> siempre lo mismo al anterior; crece en línea recta. En la <strong>geométrica</strong> se obtiene <em>multiplicando</em> siempre por lo mismo; crece de forma explosiva. La diferencia entre ambas es la diferencia entre un sueldo y un interés compuesto.', v: 'progresion aritmetica geometrica sucesion razon diferencia', i: 'fn-sucesiones' },
{ t: 'Límite', d: 'El valor al que se acerca una función cuando la variable se aproxima a un punto. Lo esencial es que <strong>no mira lo que pasa en el punto</strong>, sino hacia dónde se dirige, y por eso puede existir aunque la función ni siquiera esté definida allí. Sin esa distinción no habría derivadas.', i: 'fn-limites' },
{ t: 'Indeterminación', d: 'Una expresión como 0/0 o ∞−∞ que aparece al sustituir y que no decide nada por sí sola: no significa que el límite no exista, sino que hay que trabajar más para averiguarlo. El nombre lo dice: está sin determinar, no está prohibida.', v: 'indeterminacion indeterminaciones', i: 'fn-limites' },
{ t: 'Continuidad', d: 'Una función es continua en un punto si el límite existe, la función existe allí y además <strong>coinciden</strong>. En la práctica: se puede dibujar sin levantar el lápiz. En ingeniería los saltos rompen cosas, y por eso las curvas de una autopista no pasan de recta a círculo de golpe.', v: 'continuidad continua discontinuidad', i: 'fn-limites' },
{ t: 'Derivada', d: 'La pendiente de la recta tangente en un punto, o dicho de otro modo, el <strong>ritmo instantáneo de cambio</strong>. Las dos lecturas importan y son la misma operación: si la función es la posición, su derivada es la velocidad; si es el número de contagiados, es la velocidad de contagio.', v: 'derivada derivar derivadas', i: 'fn-derivadas' },
{ t: 'Recta tangente', d: 'La recta que toca a la curva en un punto y lleva su misma pendiente. Es la mejor aproximación recta de la curva cerca de ese punto, y de ahí que la derivada sirva para estimar.', v: 'tangente secante', i: 'fn-derivadas' },
{ t: 'Regla de la cadena', d: 'La regla para derivar una función metida dentro de otra: se deriva la de fuera dejando lo de dentro intacto y se multiplica por la derivada de lo de dentro. Es la que más cuesta y la que más se usa. Truco para no olvidar el segundo factor: pregúntate siempre si lo de dentro es simplemente x.', v: 'regla de la cadena composicion', i: 'fn-derivadas' },
{ t: 'Punto crítico', d: 'Un punto donde la derivada vale cero, es decir, donde la curva está momentáneamente llana. Es <em>candidato</em> a máximo o mínimo, no garantía: en x³ la derivada se anula en el origen y la función sigue subiendo.', v: 'punto critico extremo maximo minimo', i: 'fn-aplicaciones' },
{ t: 'Punto de inflexión', d: 'El punto donde la curva deja de doblarse hacia un lado y empieza a doblarse hacia el otro. En una epidemia es el día en que la cosa empieza a mejorar, aunque los casos totales sigan subiendo.', v: 'inflexion curvatura concava convexa', i: 'fn-aplicaciones' },
{ t: 'Optimizar', d: 'Buscar el valor máximo o mínimo de una magnitud. El método convierte «encontrar lo mejor» en «resolver una ecuación»: se escribe la magnitud en función de una variable, se deriva y se iguala a cero. Es lo que hace un GPS al buscar la ruta más corta y lo que hace una inteligencia artificial al entrenarse.', v: 'optimizar optimizacion maximo minimo', i: 'fn-aplicaciones' },
{ t: 'Primitiva', d: 'Una función cuya derivada es la que te han dado. Integrar es buscarla, es decir, deshacer una derivada. Hay infinitas primitivas de la misma función, todas iguales salvo una constante, y por eso aparece siempre el «+C».', v: 'primitiva integral indefinida constante de integracion', i: 'fn-integral-indef' },
{ t: 'Integral definida', d: 'El área encerrada entre la curva y el eje en un tramo, entendida como el límite de sumar infinitos rectangulitos cada vez más finos. La regla de Barrow es el atajo que convierte esa suma infinita en una simple resta de dos valores.', v: 'integral definida area barrow', i: 'fn-integral-def' },
{ t: 'Región factible', d: 'En programación lineal, la zona del plano donde se cumplen todas las restricciones a la vez. El óptimo está siempre en uno de sus vértices, y eso es lo que convierte un problema con infinitas posibilidades en una lista corta que revisar.', v: 'region factible programacion lineal restricciones vertices', i: 'fn-prog-lineal' },

/* ---------------- probabilidad y estadística ---------------- */
{ t: 'Suceso', d: 'Un conjunto de resultados posibles de un experimento. «Sacar par» al tirar un dado es el suceso {2,4,6}. Como son conjuntos, todo lo que sabes de uniones e intersecciones vale aquí con otro vocabulario.', v: 'suceso sucesos espacio muestral', i: 'pe-probabilidad' },
{ t: 'Regla de Laplace', d: 'Probabilidad igual a casos favorables entre casos posibles. Tiene una condición que se olvida constantemente y que es donde vive el negocio de los casinos: <strong>solo vale si todos los casos son igual de probables</strong>.', v: 'laplace favorables posibles', i: 'pe-probabilidad' },
{ t: 'Sucesos incompatibles', d: 'Los que no pueden ocurrir a la vez. No confundir con independientes: dos sucesos incompatibles son máximamente <em>dependientes</em>, porque si ocurre uno ya sabes con certeza que el otro no.', v: 'incompatibles excluyentes', i: 'pe-probabilidad' },
{ t: 'Sucesos independientes', d: 'Aquellos en los que saber que ha ocurrido uno no cambia la probabilidad del otro. Entonces, y solo entonces, la probabilidad de que ocurran los dos es el producto de las suyas.', v: 'independientes independencia', i: 'pe-condicionada' },
{ t: 'Probabilidad condicionada', d: 'La probabilidad de A <em>sabiendo que</em> ha ocurrido B; se escribe P(A|B) con una barra que se lee «sabiendo que». Enterarse de algo reduce el mundo de posibilidades, y la fórmula no hace más que recalcular dentro de ese mundo más pequeño.', v: 'condicionada condicional barra', i: 'pe-condicionada' },
{ t: 'Teorema de Bayes', d: 'La fórmula que da la vuelta a una probabilidad condicionada: pasa de «probabilidad del efecto dada la causa» a «probabilidad de la causa dado el efecto». Su conclusión desconcierta: con una enfermedad rara, la mayoría de los positivos de una prueba muy buena pueden ser falsos.', v: 'bayes teorema de bayes', i: 'pe-condicionada' },
{ t: 'Media, mediana y moda', d: 'Tres formas de resumir unos datos con un número. La <strong>media</strong> reparte el total a partes iguales; la <strong>mediana</strong> es el valor que deja la mitad a cada lado; la <strong>moda</strong> es el que más se repite. Con un dato extremo se separan muchísimo, y por eso los informes de salarios serios dan la mediana.', v: 'media mediana moda promedio centralizacion', i: 'pe-descriptiva' },
{ t: 'Varianza y desviación típica', d: 'Miden lo dispersos que están los datos respecto a su media. La <strong>varianza</strong> promedia las distancias al cuadrado; la <strong>desviación típica</strong> es su raíz, y tiene la ventaja de estar en las mismas unidades que los datos. En una inversión, la desviación es literalmente lo que se llama riesgo.', v: 'varianza desviacion tipica dispersion sigma', i: 'pe-descriptiva' },
{ t: 'Covarianza', d: 'Mide si dos variables se desvían de su media hacia el mismo lado. Tiene un defecto para comparar: depende de las unidades. El coeficiente de correlación lo arregla dividiendo por las desviaciones típicas.', i: 'pe-bidimensional' },
{ t: 'Coeficiente de correlación', d: 'Un número entre −1 y 1 que mide cuánto se parece una nube de puntos a una recta. Que valga casi cero significa que no hay relación <em>lineal</em>, no que no haya relación: los puntos de una parábola perfecta dan casi cero. Y correlación nunca implica causalidad.', v: 'correlacion pearson r', i: 'pe-bidimensional' },
{ t: 'Recta de regresión', d: 'La recta que mejor representa una nube de puntos, definida como la que hace mínima la suma de los cuadrados de las distancias verticales. Sirve para predecir, con dos cautelas: que la correlación sea alta y que no se extrapole fuera del rango observado.', v: 'regresion minimos cuadrados', i: 'pe-bidimensional' },
{ t: 'Distribución binomial', d: 'El modelo de contar éxitos en un número fijo de intentos independientes con la misma probabilidad cada uno. Es el modelo del control de calidad y de los ensayos clínicos: cuántas piezas defectuosas en un lote, cuántos pacientes mejoran de los tratados.', v: 'binomial bernoulli', i: 'pe-binomial' },
{ t: 'Distribución normal', d: 'La campana de Gauss. Aparece por todas partes por una razón profunda: cuando muchos efectos pequeños e independientes se suman, el resultado tiende a ser normal, digan lo que digan las causas por separado.', v: 'normal gauss campana', i: 'pe-normal' },
{ t: 'Tipificar', d: 'Transformar un dato en «a cuántas desviaciones típicas está de la media». Sirve para comparar cosas medidas en unidades distintas: si tu nota está a 1,5 desviaciones por encima en Matemáticas y a 0,8 en Lengua, has ido mejor en Matemáticas aunque el número fuera más bajo.', v: 'tipificar tipificacion z estandarizar', i: 'pe-normal' },
{ t: 'Intervalo de confianza', d: 'Un rango dentro del cual se estima que está el valor real, con un nivel de confianza declarado. Es el «±3 puntos» de las encuestas. Su anchura depende de la raíz del tamaño de la muestra, y por eso para reducir el error a la mitad hay que cuadruplicarla.', v: 'intervalo de confianza margen de error', i: 'pe-inferencia' },
{ t: 'Contraste de hipótesis', d: 'El procedimiento para decidir, con datos, si una afirmación se sostiene o no. Es como se aprueba un medicamento. Tiene una patología conocida: probando muchas hipótesis, alguna sale «significativa» por pura suerte.', v: 'contraste hipotesis significativo p-valor', i: 'pe-inferencia' },

/* ---------------- bloques 7 a 11: mas alla del Bachillerato ---------------- */
{ t: 'Espacio vectorial', d: 'Un conjunto donde se puede sumar y multiplicar por números respetando las reglas de siempre. Lo potente es que no habla solo de flechas: los polinomios, las matrices y las funciones forman espacios vectoriales, y por eso todo lo que demuestres aquí vale para todos ellos.', v: 'espacio vectorial base dimension', i: 'av-espacios' },
{ t: 'Base y dimensión', d: 'Una <strong>base</strong> es un conjunto mínimo de vectores con los que se puede construir todo lo demás combinándolos. La <strong>dimensión</strong> es cuántos hacen falta. Cambiar de base es lo que hace un JPEG: escribir lo mismo en un sistema donde casi todas las coordenadas salen despreciables.', v: 'base dimension independencia lineal', i: 'av-espacios' },
{ t: 'Núcleo e imagen', d: 'De una aplicación lineal, el <strong>núcleo</strong> es lo que se aplasta hasta desaparecer y la <strong>imagen</strong> es hasta dónde llega lo que sale. Si el núcleo no es trivial, distintas entradas dan la misma salida y ya no se puede volver atrás: eso es reducir la resolución de una foto.', v: 'nucleo imagen kernel rango', i: 'av-espacios' },
{ t: 'Autovalor y autovector', d: 'Un <strong>autovector</strong> es una dirección que la transformación no tuerce: solo la estira o la encoge. Cuánto la estira es su <strong>autovalor</strong>. En una estructura son sus frecuencias propias, y conocerlas es lo que evita que un puente entre en resonancia.', v: 'autovalor autovector valor propio diagonalizar', i: 'av-lineal' },
{ t: 'Cadena de Markov', d: 'Un proceso que salta entre estados donde la probabilidad del siguiente paso depende solo de dónde estás ahora, no de cómo llegaste. Su distribución estacionaria —el reparto que ya no cambia a largo plazo— es el algoritmo con el que Google ordenó la web.', v: 'markov estacionaria transicion absorbente', i: 'av-markov' },
{ t: 'Ecuación diferencial', d: 'Una ecuación cuya incógnita es una <em>función</em> y que relaciona esa función con sus derivadas. Dice cómo cambia algo, y resolverla es averiguar cómo es. Casi toda la física está escrita así, empezando por F = ma.', v: 'ecuacion diferencial edo edp', i: 'av-edo' },
{ t: 'Punto de equilibrio', d: 'Un estado en el que el sistema se queda quieto. Lo decisivo es si es <strong>estable</strong> —si al apartarlo un poco vuelve— o <strong>inestable</strong>. Un péndulo colgando es estable; el mismo péndulo invertido no lo es, y mantenerlo exige corregir cien veces por segundo.', v: 'equilibrio estable inestable', i: 'av-sistemas-dinamicos' },
{ t: 'Caos', d: 'Un sistema es caótico cuando dos estados iniciales casi idénticos acaban separándose por completo. No significa aleatorio: las reglas son deterministas. Significa impredecible en la práctica, porque nunca se conocen los datos con precisión infinita. Es la razón de que el tiempo no se pueda predecir a más de dos semanas.', v: 'caos efecto mariposa lorenz sensible', i: 'av-caos' },
{ t: 'Fractal', d: 'Una figura que se repite a distintas escalas y cuya dimensión no es un número entero. Esa dimensión fraccionaria mide rugosidad, y se usa en medicina: la ramificación de los vasos de una retina tiene una dimensión característica, y desviarse de ella es señal de enfermedad.', v: 'fractal dimension fraccionaria', i: 'av-caos' },
{ t: 'Derivada parcial', d: 'La derivada de una función de varias variables respecto a una de ellas, tratando las demás como si fueran números fijos. Se escribe con una d redondeada, ∂, para distinguirla. Responde a «si muevo solo esto, ¿cuánto cambia el resultado?».', v: 'parcial parciales', i: 'av-vectorial' },
{ t: 'Gradiente', d: 'El vector que apunta hacia donde una función crece más deprisa. Es la brújula de casi todo lo que se optimiza hoy: entrenar un modelo de inteligencia artificial consiste en calcular gradientes y caminar en sentido contrario, cuesta abajo.', v: 'gradiente nabla', i: 'av-vectorial' },
{ t: 'Divergencia y rotacional', d: 'Dos formas de interrogar a un campo vectorial. La <strong>divergencia</strong> mide cuánto sale menos cuánto entra en un punto: positiva es una fuente, negativa un sumidero. El <strong>rotacional</strong> mide cuánto tiende a girar el campo allí.', v: 'divergencia rotacional campo', i: 'av-vectorial' },
{ t: 'Serie de Fourier', d: 'La descomposición de una función periódica en suma de senos y cosenos. Su versión general, la transformada, está dentro de un MP3, de un JPEG, de una llamada de móvil y de una resonancia magnética: es probablemente la matemática que más veces se ejecuta al día en el mundo.', v: 'fourier serie transformada espectro frecuencia', i: 'av-fourier' },
{ t: 'Curvatura', d: 'Cuánto se aparta una curva de ser recta, o una superficie de ser plana. El teorema egregio de Gauss dice que la curvatura de una superficie es intrínseca, y de ahí que no exista un mapa plano fiel de la Tierra: ninguna proyección puede conservarlo todo.', v: 'curvatura gauss egregio', i: 'av-geodif' },
{ t: 'Geodésica', d: 'El camino más corto sobre una superficie curva. Sobre una esfera no es la línea recta del mapa sino un arco de círculo máximo, y por eso un vuelo de Madrid a Nueva York sube hacia Groenlandia. En relatividad, un planeta en órbita simplemente sigue su geodésica.', v: 'geodesica camino mas corto', i: 'av-geodif' },
{ t: 'Topología', d: 'El estudio de las propiedades que se conservan al deformar sin romper ni pegar. Para un topólogo, una taza y un donut son la misma cosa, porque los dos tienen un agujero. Lo que parece la rama más abstracta se usa hoy para clasificar tumores y planificar movimientos de robots.', v: 'topologia genero agujeros homeomorfo', i: 'av-topologia' },
{ t: 'Grupo', d: 'Un conjunto con una operación que cumple cuatro reglas mínimas. Sirve para estudiar simetrías: los giros de un cristal, las permutaciones de las soluciones de una ecuación. Con esta idea se demostró que no puede existir fórmula para las ecuaciones de quinto grado.', v: 'grupo grupos simetria galois', i: 'av-grupos' },
{ t: 'Numerable', d: 'Un conjunto infinito es numerable si se puede emparejar uno a uno con los números naturales, es decir, si se puede hacer una lista aunque no acabe nunca. Los racionales lo son; los reales no, y demostrarlo fue lo que abrió la puerta a distintos tamaños de infinito.', v: 'numerable cardinalidad cantor infinito', i: 'av-infinito' },
{ t: 'Grafo', d: 'Unos puntos y unas líneas que unen algunos de ellos. Nada más, y con eso se modelan una red de metro, las amistades de una red social, las páginas enlazadas de internet o las tareas de una obra con sus dependencias.', v: 'grafo vertice arista nodo', i: 'av-grafos' },
{ t: 'Entropía', d: 'La medida de la incertidumbre de una fuente de información: cuánta sorpresa hay, de media, en cada mensaje. Fija un límite exacto a cuánto se puede comprimir algo sin perder nada, y por eso un archivo ZIP ya no se puede volver a comprimir.', v: 'entropia informacion shannon', i: 'av-informacion' },
{ t: 'Equilibrio de Nash', d: 'Una combinación de estrategias en la que nadie mejora cambiando la suya en solitario. Ojo al matiz: no dice que sea la mejor situación para todos, solo que nadie tiene incentivo individual para moverse. Explica las guerras de precios y por qué cuesta tanto un acuerdo climático.', v: 'nash equilibrio juegos dilema prisionero', i: 'av-juegos' },
{ t: 'Método iterativo', d: 'El que se acerca a la solución repitiendo un paso que la mejora, en lugar de dar con ella de golpe. Bisección y Newton-Raphson lo son. Se usan cuando no hay fórmula, que es la situación normal fuera de los libros de texto.', v: 'iterativo iteracion biseccion newton raphson convergencia', i: 'av-numerico' },

/* ---------------- cibernética ---------------- */
{ t: 'Cibernética', d: 'La disciplina que estudia el control y la comunicación, con la tesis de que funcionan igual en una máquina y en un ser vivo. La bautizó Wiener en 1948 tomando la palabra griega <em>kybernetes</em>, «timonel»; de la misma raíz vienen «gobernar» y «gobierno».', v: 'cibernetica wiener kybernetes', i: 'cib-realimentacion' },
{ t: 'Realimentación', d: 'Que un sistema mida su propio resultado y use la diferencia con lo que quería para corregirse. Es la idea madre de todo el bloque, y lo que la hace rara es su circularidad: el efecto vuelve a la entrada y deja de estar claro quién es la causa de quién.', v: 'realimentacion retroalimentacion feedback bucle lazo', i: 'cib-realimentacion' },
{ t: 'Realimentación negativa', d: 'Aquella en la que la corrección se opone a la desviación, de modo que el sistema se estabiliza. Se llama negativa por el signo, no porque sea mala: es la que mantiene tu temperatura corporal y la que hace que un termostato funcione.', v: 'negativa estabiliza', i: 'cib-realimentacion' },
{ t: 'Realimentación positiva', d: 'Aquella en la que la corrección va a favor de la desviación, de modo que la amplifica. El chirrido de un micrófono junto a su altavoz, un pánico bancario o el deshielo que acelera el calentamiento. No es «mala»: es la que convierte un cambio pequeño en uno grande.', v: 'positiva amplifica circulo vicioso', i: 'cib-realimentacion' },
{ t: 'Ganancia', d: 'Cuánto corrige un regulador por cada unidad de error; suele escribirse $K$. Su efecto no es el intuitivo: subirla acelera la respuesta hasta cierto punto, y pasado ese punto aparecen sobrepaso, oscilación y descontrol.', v: 'ganancia gain K', i: 'cib-realimentacion' },
{ t: 'Caja negra', d: 'Un sistema que no se puede abrir y que solo se conoce perturbándolo y observando su respuesta. Es la situación normal, no la excepción: así se estudia un organismo, una economía o un programa ajeno. Su límite es que dos cajas que respondan igual a todo experimento posible son indistinguibles.', v: 'caja negra black box sondear', i: 'cib-caja-negra' },
{ t: 'Estado', d: 'El conjunto de datos que hay que conocer de un sistema para saber qué hará a continuación. Si desde el mismo estado a veces hace una cosa y a veces otra, no es que sea caprichoso: es que falta una variable por incluir en la descripción.', v: 'estado transicion determinado por su estado', i: 'cib-caja-negra' },
{ t: 'Variedad', d: 'El número de estados distintos que algo puede presentar. Medida en bits es $\\log_2 V$, y entonces coincide exactamente con la entropía de Shannon. Ashby insistía en que no es una propiedad del objeto sino del observador: depende de qué distinciones haga quien mira.', v: 'variedad ashby estados', i: 'cib-variedad' },
{ t: 'Ley de la variedad requerida', d: 'Para regular del todo un sistema hace falta al menos tanta variedad en el regulador como en las perturbaciones: $V_R \\ge V_D$. Suele citarse como «solo la variedad puede absorber variedad». Su consecuencia práctica es dura: si el regulador tiene menos jugadas, su porcentaje de fallo está fijado de antemano y no lo arregla esforzarse más.', v: 'variedad requerida ashby requisite variety', i: 'cib-variedad' },
{ t: 'Atenuar y amplificar', d: 'Las dos salidas a un problema de variedad. <strong>Amplificar</strong> es dar más respuestas al regulador; <strong>atenuar</strong>, reducir las situaciones que pueden presentarse. Un formulario con opciones cerradas atenúa; contratar más gente amplifica.', v: 'atenuar amplificar variedad', i: 'cib-variedad' },
{ t: 'Teorema del buen regulador', d: 'Resultado de Conant y Ashby (1970): todo regulador óptimo de un sistema contiene necesariamente un modelo de ese sistema. «Modelo» significa aquí hacer las mismas distinciones, no entender ni representar conscientemente. Su lectura práctica: si un regulador falla siempre igual, lo que le falta es una distinción, no potencia.', v: 'buen regulador conant modelo', i: 'cib-segundo-orden' },
{ t: 'Señal de error', d: 'La diferencia entre lo que se quiere y lo que hay, $e = r - y$. Es lo único que mira un controlador, hasta el punto de que no necesita saber qué está controlando. Que sea negativa significa que te has pasado.', v: 'error consigna referencia setpoint', i: 'cib-control' },
{ t: 'Controlador PID', d: 'El controlador más usado del mundo. Corrige con tres términos: el error de ahora (<strong>proporcional</strong>), el error acumulado (<strong>integral</strong>, que es la memoria) y el ritmo al que cambia (<strong>derivativo</strong>, que es la anticipación). Ajustar sus tres coeficientes se llama sintonizar.', v: 'pid proporcional integral derivativo sintonizar', i: 'cib-control' },
{ t: 'Error en régimen permanente', d: 'El hueco que queda entre el objetivo y lo conseguido cuando el sistema ya se ha estabilizado. Aparece con control solo proporcional y una carga constante, porque compensar la carga exige una corrección permanente y esa corrección exige un error permanente. Lo cierra el término integral.', v: 'regimen permanente error residual offset', i: 'cib-control' },
{ t: 'Variable esencial', d: 'Aquella que debe permanecer dentro de unos límites o el sistema no sobrevive: la temperatura corporal, el pH de la sangre, la liquidez de una empresa. Se distingue de las instrumentales, que pueden variar muchísimo y de hecho varían para proteger a las esenciales.', v: 'esencial instrumental limites', i: 'cib-homeostasis' },
{ t: 'Homeostasis', d: 'Mantener las variables esenciales dentro de sus límites pese a las perturbaciones. La palabra es del fisiólogo Cannon (1926) y significa literalmente «permanecer igual»; Ashby la convirtió en matemáticas.', v: 'homeostasis cannon equilibrio interno', i: 'cib-homeostasis' },
{ t: 'Ultraestabilidad', d: 'La propiedad de un sistema que, además de corregirse, sabe <strong>reconfigurarse</strong> cuando cambian las reglas del mundo. El homeostato de Ashby lo conseguía sorteando al azar sus coeficientes cada vez que una variable esencial se salía de rango: adaptación sin inteligencia.', v: 'ultraestable ultraestabilidad homeostato uniselector', i: 'cib-homeostasis' },
{ t: 'Retardo', d: 'El tiempo entre una acción correctora y su efecto observable. Obliga a decidir con información vieja y consume margen de estabilidad: una ganancia segura sin demora puede oscilar con ella. Su regla práctica es contraintuitiva: con retardo hay que corregir <em>menos</em> y esperar.', v: 'retardo demora desfase ducha', i: 'cib-retardos' },
{ t: 'Efecto látigo', d: 'La oscilación creciente de una cadena de suministro: una variación pequeña de la demanda se amplifica en cada eslabón por culpa de los retardos, y acaba en un vaivén de almacenes llenos y vacíos. Cuanto más lejos del cliente, más violento.', v: 'latigo bullwhip cadena suministro forrester', i: 'cib-retardos' },
{ t: 'Media móvil', d: 'El filtro más sencillo y probablemente el más usado: sustituir cada valor por el promedio de los $k$ últimos. Funciona porque la señal cambia despacio y el ruido salta sin memoria, así que se cancela solo. Su precio es el retraso, que crece con la ventana.', v: 'media movil ventana suavizado filtro', i: 'cib-filtrado' },
{ t: 'Señal y ruido', d: 'Lo medido es la suma de la señal verdadera y el ruido. Parece un despeje —restar el ruido— y no lo es, porque si el ruido se conociera no sería ruido: hay que estimarlo. Todo el problema del filtrado nace de ahí.', v: 'senal ruido snr', i: 'cib-filtrado' },
{ t: 'Filtro de Kalman', d: 'Método de 1960 que combina medidas ruidosas con un modelo de cómo se mueve lo medido, y produce una estimación mejor que cualquiera de los dos por separado. Lo adoptó la NASA para el programa Apolo y hoy va dentro de cada GPS: es la razón de que el punto azul siga avanzando con sensatez al entrar en un túnel.', v: 'kalman filtro apolo gps prediccion', i: 'cib-filtrado' },
{ t: 'Autómata celular', d: 'Una cuadrícula de celdas encendidas o apagadas con una regla que solo mira a las vecinas. Con vecindad de tres celdas hay exactamente 256 reglas, y se pueden explorar todas. La regla 110 resultó ser capaz de computar cualquier cosa que compute un ordenador.', v: 'automata celular regla 110 regla 30 vida conway', i: 'cib-autoorganizacion' },
{ t: 'Emergencia', d: 'Que el conjunto tenga propiedades que no están en las piezas ni en las reglas. En el Juego de la Vida ninguna celda se mueve nunca —solo se encienden y se apagan— y sin embargo hay figuras que se desplazan. No es magia: es que saber las reglas no es lo mismo que saber sus consecuencias.', v: 'emergencia emergente autoorganizacion planeador', i: 'cib-autoorganizacion' },
{ t: 'Cibernética de segundo orden', d: 'La que incluye al observador dentro del sistema observado, frente a la de primer orden, que lo deja fuera. La formuló von Foerster: la primera es la cibernética de los sistemas observados; la segunda, la de los sistemas observadores.', v: 'segundo orden von foerster observador', i: 'cib-segundo-orden' },
{ t: 'Ley de Goodhart', d: 'Cuando una medida se convierte en objetivo, deja de ser una buena medida. Si se evalúa un hospital por el tiempo de espera, el tiempo de espera mejora y deja de informar sobre la calidad. Es el acoplamiento entre observador y observado, visto en la práctica.', v: 'goodhart indicador objetivo metrica', i: 'cib-segundo-orden' },
/* ---------------- series y convergencia ---------------- */
{ t: 'Serie', d: 'La suma de los infinitos términos de una sucesión. Ojo: no es una suma de verdad, porque nadie suma infinitas cosas. Es el <em>límite</em> de las sumas parciales, y solo significa algo cuando ese límite existe.', v: 'serie suma infinita sumatorio infinito', i: 'fn-series' },
{ t: 'Suma parcial', d: 'Lo que llevas sumado hasta el término n: $S_n = a_1 + a_2 + \\dots + a_n$. Es una suma corriente, con un número finito de sumandos. Las sumas parciales forman una sucesión, y preguntarle a esa sucesión adónde va es lo único que se hace al estudiar una serie.', v: 'suma parcial parciales sn', i: 'fn-series' },
{ t: 'Convergencia', d: 'Que algo se acerca a un valor concreto y se queda ahí. Una <strong>sucesión</strong> converge si sus términos se aproximan a un número; una <strong>serie</strong> converge si lo hacen sus sumas parciales, y entonces ese límite <em>es</em> la suma de la serie. Si no converge, se dice que diverge, y la serie no tiene suma: no es que sea difícil de calcular, es que no hay ningún número que merezca ese nombre.', v: 'convergencia converge convergente convergen', i: 'fn-series' },
{ t: 'Divergencia', d: 'Lo contrario de converger. Una serie diverge si sus sumas parciales se van al infinito o si no se deciden por ningún valor. El caso más instructivo es la serie armónica: sus términos tienden a cero y aun así la suma crece sin techo.', v: 'divergencia diverge divergente divergen', i: 'fn-series' },
{ t: 'Serie armónica', d: 'La serie $1 + \\frac12 + \\frac13 + \\frac14 + \\dots$. <strong>Diverge</strong>, aunque sus términos tiendan a cero, y esa es la razón de que no se pueda concluir que una serie converge solo porque sus términos se hagan pequeños. Lo demostró Oresme hacia 1350 agrupando los términos en bloques que doblan de tamaño: cada bloque suma más de un medio.', v: 'armonica serie armonica oresme', i: 'fn-series' },
{ t: 'p-serie', d: 'La familia $\\sum \\frac{1}{n^p}$. Converge exactamente cuando $p > 1$ y diverge cuando $p \\le 1$. Es la vara de medir con la que se compara casi cualquier otra serie: se mira el término dominante y se decide de qué lado de esa frontera cae.', v: 'p serie pserie p-serie', i: 'fn-series' },
{ t: 'Serie telescópica', d: 'Aquella en la que cada término cancela parte del siguiente, de modo que la suma parcial se pliega como un catalejo y solo sobreviven el primer trozo y el último. Es la única familia en la que se ve directamente cuánto vale $S_n$, sin criterios ni trucos.', v: 'telescopica telescopio', i: 'fn-series' },
{ t: 'Serie alternada', d: 'Aquella cuyos términos van cambiando de signo. Si los valores absolutos decrecen hasta cero, converge, aunque la serie de los valores absolutos diverja. Su ventaja práctica: al cortarla, el error es siempre menor que el primer término que has dejado fuera.', v: 'alternada alternante leibniz', i: 'fn-series' },
{ t: 'Condición necesaria de convergencia', d: 'Si una serie converge, sus términos tienen que tender a cero. Se usa siempre al revés: si <em>no</em> tienden a cero, la serie no converge y se acabó el análisis. Lo que no se puede hacer nunca es leerla en el otro sentido: que tiendan a cero no garantiza nada.', v: 'condicion necesaria termino general tiende a cero', i: 'fn-series' },

/* ---------------- Taylor ---------------- */
{ t: 'Polinomio de Taylor', d: 'El polinomio de grado n que en un punto tiene exactamente las mismas derivadas que la función, hasta la de orden n. Sirve para sustituir una función complicada por una que solo tiene sumas y productos, que es lo único que sabe hacer una máquina. De grado 1 es la recta tangente de siempre.', v: 'taylor polinomio de taylor', i: 'fn-taylor' },
{ t: 'Serie de Taylor', d: 'El polinomio de Taylor llevado al infinito: $\\sum \\frac{f^{(n)}(a)}{n!}(x-a)^n$. Solo tiene sentido donde esa serie converge, y ese es exactamente el problema que estudia el tema de series numéricas.', v: 'serie de taylor maclaurin', i: 'fn-taylor' },
{ t: 'Polinomio de Maclaurin', d: 'El polinomio de Taylor centrado en el punto $a = 0$. No es un concepto distinto, solo el caso más usado, porque cerca de cero las cuentas salen más limpias.', v: 'maclaurin', i: 'fn-taylor' },
{ t: 'Resto de Lagrange', d: 'La diferencia exacta entre una función y su polinomio de Taylor: $R_n = \\frac{f^{(n+1)}(c)}{(n+1)!}(x-a)^{n+1}$, para algún punto $c$ entre $a$ y $x$. Nadie sabe cuál es ese $c$, y da igual: basta con acotar la derivada en el intervalo para <strong>garantizar</strong> cuántas cifras son correctas. Sin él, una aproximación sirve para dibujar pero no para calcular.', v: 'resto lagrange error de taylor cota del error', i: 'fn-taylor' },
{ t: 'Radio de convergencia', d: 'La distancia alrededor del punto de apoyo dentro de la cual la serie de Taylor converge. Fuera de ese radio no es que la aproximación sea mala: es que la serie no suma nada. Para $e^x$, el seno y el coseno el radio es infinito; para $\\frac{1}{1-x}$ vale 1.', v: 'radio de convergencia', i: 'fn-taylor' },
{ t: 'Derivada n-ésima', d: 'El resultado de derivar n veces seguidas. Se escribe $f^{(n)}$, con el número entre paréntesis para que no se confunda con una potencia: $f^{(3)}$ es la tercera derivada y $f^3$ es la función al cubo. Para las primeras se siguen usando las comillas.', v: 'derivada n-esima enesima orden superior', i: 'fn-taylor' },
{ t: 'Teorema de Rolle', d: 'Si una función continua y derivable sale de una altura y vuelve a la misma altura, en algún punto de en medio su tangente es horizontal. Es un teorema de existencia: dice que ese punto hay, no cuál es ni cuántos.', v: 'rolle', i: 'fn-derivadas' },
{ t: 'Teorema del valor medio', d: 'Rolle inclinado: en algún punto la pendiente instantánea coincide con la pendiente media del tramo. Si has hecho 180 km en dos horas, en algún instante ibas exactamente a 90 km/h. Es la base de los radares de tramo y del resto de Lagrange.', v: 'valor medio lagrange teorema del valor medio tvm', i: 'fn-derivadas' },

/* ---------------- matematica financiera ---------------- */
{ t: 'Valor actual', d: 'Lo que vale hoy una cantidad de dinero que se cobrará en el futuro: $VA = \\frac{C_n}{(1+i)^n}$. La operación se llama <em>descontar</em>, y es imprescindible porque sumar euros de años distintos sin traerlos a la misma fecha es como sumar metros y segundos.', v: 'valor actual descuento descontar', i: 'fn-finanzas' },
{ t: 'TIN y TAE', d: 'El <strong>TIN</strong> es el tipo nominal, el número grande del anuncio; no tiene en cuenta cada cuánto se cobran los intereses, así que no sirve para comparar. La <strong>TAE</strong> es lo que el dinero cuesta de verdad en un año, incluyendo la frecuencia de cobro y las comisiones obligatorias. Compara siempre TAE con TAE.', v: 'tin tae tipo nominal tasa anual equivalente', i: 'fn-finanzas' },
{ t: 'Cuota (sistema francés)', d: 'El pago constante con el que se devuelve un préstamo: $c = P\\frac{i}{1-(1+i)^{-n}}$. Sale de igualar el capital prestado a la suma de todas las cuotas traídas a hoy, que es una progresión geométrica. Al principio casi toda la cuota son intereses y al final casi todo es capital.', v: 'cuota hipoteca amortizacion sistema frances prestamo', i: 'fn-finanzas' },

/* ---------------- variables continuas ---------------- */
{ t: 'Variable aleatoria continua', d: 'Aquella que puede tomar cualquier valor de un intervalo, como una estatura o un tiempo de espera. La diferencia práctica con una discreta es radical: la probabilidad de un valor concreto es <strong>cero</strong>, y las únicas preguntas con sentido son sobre intervalos.', v: 'variable continua aleatoria continua', i: 'pe-continuas' },
{ t: 'Función de densidad', d: 'La curva $f$ cuya área bajo un tramo da la probabilidad de caer en ese tramo. Cumple dos cosas y nada más: no es negativa y encierra área total 1. <strong>No</strong> es una probabilidad y puede valer más de 1; lo que nunca pasa de 1 es el área. La palabra correcta es la de la física: densidad, no masa.', v: 'densidad funcion de densidad', i: 'pe-continuas' },
{ t: 'Función de distribución', d: 'La que acumula toda la probabilidad que hay a la izquierda: $F(x) = P(X \\le x)$. Con ella cualquier probabilidad es una resta, $P(a \\le X \\le b) = F(b)-F(a)$, que es la regla de Barrow con otro nombre. Y su derivada es la densidad.', v: 'funcion de distribucion acumulada', i: 'pe-continuas' },
{ t: 'Distribución uniforme', d: 'Aquella en la que todos los valores de un intervalo son igual de probables. Su densidad es una meseta plana de altura $\\frac{1}{b-a}$, forzada por que el área tenga que valer 1. Es la que genera un ordenador al pedir un número al azar.', v: 'uniforme distribucion uniforme', i: 'pe-continuas' },
{ t: 'Distribución exponencial', d: 'Modela el tiempo hasta que ocurre algo que no envejece: la desintegración de un átomo, la avería de un componente, la siguiente llamada a una centralita. Su media es $1/\\lambda$ y <strong>no tiene memoria</strong>: una bombilla que lleva mil horas encendida tiene la misma expectativa que una nueva.', v: 'exponencial sin memoria lambda', i: 'pe-continuas' },

/* ---------------- inferencia causal ---------------- */
{ t: 'Variable de confusión', d: 'Una tercera variable que influye a la vez sobre la causa supuesta y sobre el efecto supuesto, y que por tanto los hace aparecer correlacionados sin que uno cause el otro. Su firma es inconfundible: la correlación es real, los datos son correctos y la conclusión es falsa. El calor detrás de los helados y los ahogamientos.', v: 'confusion confusora tercera variable confundidora', i: 'pe-causal' },
{ t: 'Paradoja de Simpson', d: 'El caso extremo de confusión: una asociación puede invertirse al separar los datos por una tercera variable. Un tratamiento puede ser mejor para los casos fáciles, mejor para los difíciles y peor en el total, si no se ha repartido por igual entre unos y otros.', v: 'simpson paradoja de simpson', i: 'pe-causal' },
{ t: 'Aleatorización', d: 'Repartir a los participantes entre los grupos echándolo a suertes. Parece frívolo y es lo único que equilibra <strong>todas</strong> las variables de confusión, incluidas las que nadie ha medido ni pensado: la moneda no sabe nada de ellas, así que no puede favorecer a ninguna. No hace los grupos idénticos, los hace comparables.', v: 'aleatorizacion aleatorizar sorteo azar ensayo aleatorizado', i: 'pe-causal' },
{ t: 'Grupo de control', d: 'El grupo que no recibe el tratamiento y sirve de comparación. Sin él no se sabe qué habría pasado igualmente, y mucha gente mejora sola: casi toda la tos se cura en diez días con jarabe o sin él.', v: 'control grupo de control testigo', i: 'pe-causal' },
{ t: 'Placebo y doble ciego', d: 'El <strong>placebo</strong> es un tratamiento sin principio activo, y sirve para separar el efecto del fármaco del efecto de creerse tratado, que es real y medible. El <strong>doble ciego</strong> añade que tampoco quien evalúa sabe qué ha recibido cada uno, para que no sesgue la medición sin querer.', v: 'placebo ciego doble ciego cegamiento', i: 'pe-causal' },
{ t: 'Sesgo de selección', d: 'El que aparece cuando los datos que tienes han pasado por un filtro que los relaciona con lo que quieres medir. El ejemplo clásico son los aviones que vuelven del combate con impactos en las alas: no es que las alas sean lo vulnerable, es que los alcanzados en el motor no volvieron.', v: 'seleccion sesgo superviviente supervivencia wald', i: 'pe-causal' },
{ t: 'Experimento natural', d: 'Una situación en la que algo parecido a un sorteo ha ocurrido por su cuenta: una ley que entra en vigor en una región y no en la vecina, una lotería que decide quién hace el servicio militar. Es el recurso cuando aleatorizar es imposible o inaceptable.', v: 'experimento natural cuasiexperimento', i: 'pe-causal' },

/* ---------------- completitud de los reales ---------------- */
{ t: 'Cota superior', d: 'Un número que ningún elemento del conjunto supera. Un conjunto puede tener infinitas cotas o ninguna; si tiene al menos una, se dice que está acotado superiormente.', v: 'cota superior acotado cota', i: 'av-reales' },
{ t: 'Supremo', d: 'La <strong>menor</strong> de las cotas superiores de un conjunto: su borde por arriba, pertenezca o no al conjunto. El intervalo $[0,1)$ no tiene máximo y sin embargo su supremo es 1. Cuando el supremo pertenece al conjunto, coincide con el máximo.', v: 'supremo sup extremo superior', i: 'av-reales' },
{ t: 'Ínfimo', d: 'La mayor de las cotas inferiores: el borde por abajo. El conjunto $\\{1, \\frac12, \\frac13, \\dots\\}$ tiene ínfimo 0 aunque ningún elemento valga 0, y eso es exactamente lo que significa que su límite sea cero.', v: 'infimo inf extremo inferior', i: 'av-reales' },
{ t: 'Completitud', d: 'La propiedad que distingue $\\mathbb{R}$ de $\\mathbb{Q}$: todo conjunto no vacío y acotado superiormente tiene supremo. Dicho en corto, que la recta real <strong>no tiene agujeros</strong>. Sin ella se caen Bolzano, el teorema del valor intermedio, la convergencia de las sucesiones monótonas acotadas y la bisección: es decir, todo el análisis.', v: 'completitud completo axioma del supremo', i: 'av-reales' },
{ t: 'Denso', d: 'Un conjunto es denso si entre dos elementos cualesquiera hay siempre otro. Los racionales lo son, y aun así están llenos de huecos: $\\sqrt2$ falta. Denso y completo son cosas distintas, y confundirlas es el error habitual.', v: 'denso densidad de los racionales', i: 'av-reales' },

/* ---------------- computabilidad ---------------- */
{ t: 'Máquina de Turing', d: 'El modelo más simple de «calcular»: una cinta infinita, un cabezal que lee y escribe, un estado interno y una tabla finita de reglas. No tiene memoria, ni aritmética, ni bucles, y aun así no se conoce nada calculable que no pueda calcular. Tu ordenador es más rápido, no más potente.', v: 'turing maquina de turing', i: 'av-computabilidad' },
{ t: 'Tesis de Church-Turing', d: 'La convicción de que la máquina de Turing captura exactamente la noción intuitiva de «calculable». No es un teorema, porque «calculable a mano» no es un concepto matemático; es una hipótesis apoyada en que cuatro formalismos que no se parecen en nada definen la misma clase de funciones.', v: 'church turing tesis', i: 'av-computabilidad' },
{ t: 'Problema de la parada', d: 'Decidir si un programa dado, con una entrada dada, terminará alguna vez. Turing demostró en 1936 que <strong>no existe</strong> ningún programa que lo resuelva siempre, y lo hizo con el argumento diagonal de Cantor: construyendo un programa que hace lo contrario de lo que el oráculo predice de él mismo.', v: 'parada halting problema de la parada', i: 'av-computabilidad' },
{ t: 'Decidible e indecidible', d: 'Un problema es <strong>decidible</strong> si existe un algoritmo que siempre responde bien y siempre termina. Regla práctica: si la pregunta es sobre cómo está escrito un programa, suele ser decidible; si es sobre qué hace al ejecutarse, casi nunca lo es.', v: 'decidible indecidible decidibilidad', i: 'av-computabilidad' },
{ t: 'Teorema de Rice', d: 'Generaliza el problema de la parada de la peor manera posible: <em>cualquier</em> propiedad no trivial sobre el comportamiento de un programa es indecidible. Saber si dos programas hacen lo mismo, o si alguno devuelve un número negativo, no se puede decidir en general.', v: 'rice teorema de rice', i: 'av-computabilidad' },
{ t: 'Teoremas de incompletitud', d: 'Los dos resultados de Gödel de 1931. El primero: en todo sistema consistente que hable de aritmética hay afirmaciones verdaderas que no se pueden demostrar dentro de él. El segundo: entre ellas está su propia consistencia. No dicen que las matemáticas fallen, sino que no puede haber una garantía mecánica y definitiva desde dentro.', v: 'godel incompletitud gödel', i: 'av-computabilidad' },
{ t: 'Máquina universal', d: 'Una máquina de Turing capaz de simular a cualquier otra leyendo su descripción de la cinta. Turing la construyó para demostrar un teorema negativo y resultó ser la idea de <strong>ordenador de programa almacenado</strong>: un aparato cuyo comportamiento no está en el hardware sino en unos datos.', v: 'maquina universal programa almacenado', i: 'av-computabilidad' },

/* ---------------- geometrias no euclideas ---------------- */
{ t: 'Quinto postulado', d: 'El axioma de Euclides sobre las paralelas: por un punto exterior a una recta pasa una y solo una paralela. Es <strong>independiente</strong> de los otros cuatro —no se puede demostrar ni refutar desde ellos—, y negarlo produce geometrías igual de coherentes. Se tardó dos mil años en aceptarlo.', v: 'quinto postulado paralelas playfair euclides', i: 'av-noeuclidea' },
{ t: 'Geometría hiperbólica', d: 'Aquella en la que por un punto exterior a una recta pasan infinitas paralelas. Los ángulos de un triángulo suman menos de 180°, no hay rectángulos y no hay figuras semejantes de distinto tamaño. Su curvatura es negativa: la forma de una silla de montar.', v: 'hiperbolica lobachevski bolyai', i: 'av-noeuclidea' },
{ t: 'Geometría elíptica', d: 'Aquella en la que no hay paralelas: dos rectas cualesquiera se cortan. Su modelo es la esfera, donde las «rectas» son los círculos máximos y los ángulos de un triángulo suman más de 180°. Curvatura positiva.', v: 'eliptica esferica riemann circulo maximo', i: 'av-noeuclidea' },
{ t: 'Exceso esférico', d: 'Lo que la suma de los ángulos de un triángulo esférico se pasa de 180°. Cumple $\\alpha+\\beta+\\gamma-\\pi = A/R^2$: el exceso <strong>mide el área</strong>. En un triángulo pequeño comparado con la esfera es casi cero, y por eso a escala humana la Tierra parece plana.', v: 'exceso esferico triangulo esferico', i: 'av-noeuclidea' },
{ t: 'Disco de Poincaré', d: 'Un modelo del plano hiperbólico dentro de un círculo euclídeo: las rectas son arcos perpendiculares al borde, y el borde está infinitamente lejos. Es la geometría de los grabados <em>Límite circular</em> de Escher, y la que mejor representa la estructura de las redes.', v: 'poincare disco modelo hiperbolico escher', i: 'av-noeuclidea' },

/* ---------------- añadidos tras la revisión ---------------- */
{ t: 'Esperanza', d: 'La media de una variable aleatoria: el valor alrededor del cual se reparte. Se escribe $E[X]$, con corchetes, porque no se aplica a un número sino a la variable entera. En una variable discreta es la suma de cada valor por su probabilidad; en una continua, la integral de $x\\,f(x)$. Físicamente es el centro de gravedad de la distribución: el punto donde se sostendría en equilibrio.', v: 'esperanza valor esperado media e de x centro de gravedad', i: 'pe-continuas' },
{ t: 'Tanto por uno', d: 'La forma de escribir un porcentaje como número decimal: un 3 % es 0,03. Todas las fórmulas financieras lo usan así, y meter el 3 en lugar del 0,03 es el error más repetido del tema. Para pasar de porcentaje a tanto por uno se divide entre 100.', v: 'tanto por uno porcentaje tipo interes', i: 'fn-finanzas' },
{ t: 'Registro previo', d: 'Declarar públicamente, antes de mirar los datos, qué se va a medir y cómo. Impide el juego de medir veinte variables y publicar la única que salió significativa: con veinte pruebas al 5 %, una sale por puro azar. Su ausencia explica buena parte de los resultados científicos que luego no se han podido reproducir.', v: 'registro previo preregistro multiples comparaciones', i: 'pe-causal' },
{ t: 'Factorial', d: 'El producto de todos los enteros desde 1 hasta n, y se escribe $n!$: $5! = 5\\cdot4\\cdot3\\cdot2\\cdot1 = 120$. Aparece en combinatoria, al contar ordenaciones, y en los polinomios de Taylor, donde deshace el número que la derivada va multiplicando. Crece más deprisa que cualquier potencia, y por eso las series con factoriales en el denominador convergen tan bien.', v: 'factorial n! exclamacion', i: 'pe-combinatoria' },
];
